import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.vDgOMd_y.js";const k=JSON.parse('{"title":"组建你的团队","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/team.md","filePath":"zh/guides/team.md"}'),s={name:"zh/guides/team.md"};function d(n,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/zh/guides/team.md for this page in Markdown format</div><h1 id="组建你的团队" tabindex="-1">组建你的团队 <a class="header-anchor" href="#组建你的团队" aria-label="Permalink to &quot;组建你的团队&quot;">​</a></h1><p>一个人写代码是单打独斗。有了 AI 团队，你可以像搭班子一样——给每个成员挂上职位、配好提示词、挑趁手的模型，然后随时指挥。</p><h2 id="雇佣-一句话就能招人" tabindex="-1">雇佣：一句话就能招人 <a class="header-anchor" href="#雇佣-一句话就能招人" aria-label="Permalink to &quot;雇佣：一句话就能招人&quot;">​</a></h2><p>对主 Agent 说&quot;我需要一个邮件收发的文员&quot;，它会根据你的需求自动决定名字、职位（<code>role</code>）、系统提示词和模型，直接写入 <code>~/.kimi-code/agents/&lt;name&gt;.md</code>——整个过程不需要你手写任何 agent 文件。同名已存在会报错，不会静默覆盖。</p><blockquote><p><strong>自主组队纪律</strong>：当任务需要的能力没有现成成员时，主 Agent 应自主决定新成员的 name / role / description / prompt / model，并直接执行雇佣，无需逐项请示用户。</p></blockquote><p>写完即生效。目录 watcher 自动 reload 后，新成员立即可被派遣——不需要重启 CLI。</p><p>让某个子 Agent 一直在后台待命，不给你的前台对话添堵？给这个成员的 agent 文件加上 <code>duty: true</code>，它就会免超时运行（一直轮询邮件、监控仓库都可以）。你需要它下班时，主 Agent 用 <code>TaskStop</code> 停止即可——它们不会因为超时被自动中断。</p><h2 id="排兵布阵-按模型分工" tabindex="-1">排兵布阵：按模型分工 <a class="header-anchor" href="#排兵布阵-按模型分工" aria-label="Permalink to &quot;排兵布阵：按模型分工&quot;">​</a></h2><p>你的 <code>[models]</code>（<code>config.toml</code> 中定义的模型列表）就是整个团队的可用&quot;人力池&quot;。不同任务可以交给不同的模型来执行：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;kimi-code/k3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;managed:kimi-code&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;k3&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_context_size = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">262144</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;kimi-code/kimi-for-coding&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;managed:kimi-code&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi-for-coding&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_context_size = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">262144</span></span></code></pre></div><p>换将只需一句话：&quot;coder 用 kimi2.5 太差，换成 kimi-for-coding。&quot;主 Agent 会通过 <code>[subagent.model_overrides]</code> 更新配置——这个覆盖<strong>优先级高于 profile 的 <code>model_preference</code>，但低于工具调用时显式传入的具体值</strong>。如果你想让某个成员永远绑定一个型号，在 agent 文件的 <code>model_preference</code> 字段填上对应 id 即可。</p><table tabindex="0"><thead><tr><th>层级</th><th>谁决定</th><th>范围</th></tr></thead><tbody><tr><td>工具参数</td><td>Agent 每次派发时指定</td><td>单次调用</td></tr><tr><td><code>[subagent.model_overrides]</code></td><td>主 Agent 在对话中通过 <code>TeamHire</code>/聊天指令更新</td><td>永久生效，覆盖 profile 默认</td></tr><tr><td>frontmatter <code>model_preference</code></td><td>写进 agent 文件本人</td><td>永久生效</td></tr></tbody></table><h2 id="在岗管理-随时递话、随时打断" tabindex="-1">在岗管理：随时递话、随时打断 <a class="header-anchor" href="#在岗管理-随时递话、随时打断" aria-label="Permalink to &quot;在岗管理：随时递话、随时打断&quot;">​</a></h2><p>派出去之后你怎么管？</p><ul><li><strong>后台默认</strong>：团队模式下，主 Agent 派工默认后台运行——<code>Agent</code> 工具的 <code>run_in_background</code> 省略即视为 <code>true</code>。派工立即返回 task_id，完成结果以系统消息自动送达，主 Agent 不阻塞，随时可与用户沟通。只有显式要求前台等待，才会同步阻塞。</li><li><strong>看进度</strong>：用已有 <code>/tasks</code>（即 <code>TaskList</code>）和 <code>TaskOutput</code>，查后台任务的输出与状态。</li><li><strong>递话指正</strong>：发现跑偏了？主 Agent 可以用 <code>TeamMessage</code> 直接给运行中的子 Agent 递话——默认软提醒插入当前轮次，设 <code>interrupt: true</code> 则先取消再注入新指令（效果等同你在终端连按两次 ESC）。</li><li><strong>调整并发</strong>：用 <code>TeamConcurrency</code> 查看和动态调整 session 并发上限——机器空闲时跑 4 个、紧张时降下来。配合 <code>config.toml</code> 的 <code>[subagent] max_concurrency</code> 配置，灵活控制团队吞吐。</li><li><strong>下班</strong>：用 <code>TaskStop</code> 停止运行中实例。<code>duty: true</code> 的成员需要主 Agent 主动派 <code>TaskStop</code> 才能停——它们自己不会超时自动中断。</li></ul><h2 id="绩效-完工评分" tabindex="-1">绩效：完工评分 <a class="header-anchor" href="#绩效-完工评分" aria-label="Permalink to &quot;绩效：完工评分&quot;">​</a></h2><p>任务完成了？主 Agent 会用当前平均分 + 所用模型提醒你打分。你也可以随时用 <code>TeamScore</code> 手动评分（0-100 加评语）。</p><p>每条评分记录归因到当时所用的模型 id，持久化在 <code>$KIMI_CODE_HOME/agents/performance.json</code>——按 profile 名分组、每条包含时间戳、分数、备注和运行模型。团队模式下，每次子 Agent 任务完成还会自动记录一条工时（时长、工作内容梗概、模型、并发度），与评分一样存在 <code>performance.json</code> 中（各 FIFO 50 条），方便你预估排期。开启团队模式后，<code>Agent</code> 工具的成员列表里会直接显示每人的平均分。</p><p>当某个成员在当前模型下持续低分时，说明这个&quot;成员 × 模型&quot;搭配不合适，主 Agent 应通过 <code>[subagent.model_overrides]</code> 自动换模型或建议你从 <code>[models]</code> 列表中换一个试试。</p><h2 id="team-一目了然" tabindex="-1">/team：一目了然 <a class="header-anchor" href="#team-一目了然" aria-label="Permalink to &quot;/team：一目了然&quot;">​</a></h2><p>团队模式默认关闭。用 <code>/team on</code> 开启后，五个管理工具（<code>TeamHire</code>、<code>TeamFire</code>、<code>TeamScore</code>、<code>TeamMessage</code>、<code>TeamConcurrency</code>）才对主 Agent 可见。<code>/team off</code> 可随时关闭。</p><p>在终端输入 <code>/team</code>，打开团队总览面板——全员职位、生效模型、平均分和评分次数一览无余。每个子 Agent 的调用卡片也会显示&quot;名字 · 职位 · 模型 · 上次评分&quot;。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li><a href="./../customization/agents.html">Agent 字段参考</a> — Frontmatter 字段的完整说明</li><li><a href="./../configuration/config-files.html#子代理">配置文件 — <code>model_overrides</code></a> — <code>[subagent.model_overrides]</code> 配置详情</li></ul>`,25)])])}const g=t(s,[["render",d]]);export{k as __pageData,g as default};
